import heapq, itertools
edges = {'S': [('A', 4), ('E', 1)], 'A': [('B', 2)], 'B': [('C', 2)], 'E': [('C', 2)],
         'C': [('D', 3)], 'D': [('G', 3)], 'G': []}
h = {'S': 0, 'A': 2, 'B': 2, 'C': 6, 'E': 6, 'D': 2, 'G': 0}  # h(S) not shown; irrelevant (S is expanded first)
def search(key, trace=False):
    cnt = itertools.count(); pq = [(0, next(cnt), 0, 'S')]; best = {'S': 0}; order = []; closed = set()
    while pq:
        k, _, g, n = heapq.heappop(pq)
        if n in closed: continue
        closed.add(n); order.append(n)
        if trace: print(f'  expand {n}: g={g}, priority={k}')
        if n == 'G': return ','.join(order)
        for m, c in edges[n]:
            if m not in closed and (m not in best or g + c < best[m]):
                best[m] = g + c; heapq.heappush(pq, (key(g + c, m), next(cnt), g + c, m))
            elif trace: print(f'    {n}->{m}: g={g+c} not better than {best[m]}, ignored')
print('A* (f=g+h):', search(lambda g, m: g + h[m], trace=True))
print('UCS (g only):', search(lambda g, m: g))
print('Greedy (h only, FIFO ties):', search(lambda g, m: h[m]))
print('inconsistent edges (h(n) > c + h(m)):', [(n, m) for n in edges for m, c in edges[n] if h[n] > c + h[m]])
